"""
    Convert a string hex byte values into a byte string. The Hex Byte values may
    or may not be space separated.
    """
def HexToByte(hexStr: Any) -> object {
    `bytes = [];
    hexStr = ''.join(hexStr.split(" "));
    for i in range(0, len(hexStr), 2) {
        `bytes.append(chr(int(hexStr[i:(i + 2)], 16)));
    }
    return ''.join(`bytes);
}

"""
    Ars: two lists of batches

    Returns True if the corresponding batches in lists are different
    Returns False otherwise
    """
def batches_shuffled(batch_list1: Any, batch_list2: Any) -> object {
    for (b1, b2) in zip(batch_list1, batch_list2) {
        if (b1 == b2) {
            return False;
        }
    }
    return True;
}

