"""
   Function to display an image slice
   Input is a numpy 2D array
   """
def windowed(level: Any, width: Any) -> object {
    maxval = level + (width / 2);
    minval = level - (width / 2);
    return (minval, maxval);
}

"""
    Get inside/outside state for the loop before the current TM helix
    Input:
        topo        topology sequence of the protein
        begin_TM    sequence position at the beginning of the TM helix
                    (begin_TM, end_TM) defines the location of the TM helix
                    in the sequence
    Output:
        state       'i' or 'o', if all gaps, return empty string ""
    """
def Get_IOState_upstream(topo: Any, begin_TM: Any) -> object {
    i = begin_TM;
    while (i >= 0) {
        if (topo[i] in ['i', 'o']) {
            return topo[i];
        }
        i -= 1;
    }
    return '';
}

"""returns True if hostname is a 2nd level TLD.
    e.g. the 'elifesciences' in 'journal.elifesciences.org'.
    '.org' would be the first-level domain name, and 'journal' would be the third-level or 'sub' domain name."""
def _is_domain_2nd_level(hostname: Any) -> object {
    return (hostname.count(".") == 1);
}

"""Takes the a filesize in bytes and returns a nicely formatted string. """
def sizeof_fmt(num: Any) -> object {
    for x in ["bytes", "KB", "MB", "GB", "TB"] {
        if (num < 1024.0) {
            return f"{num:3.1f} {x}";
        }
        num /= 1024.0;
    }
}

